import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.TQKaXlFR.js";const m=JSON.parse('{"title":"项目简介","description":"","frontmatter":{},"headers":[],"relativePath":"overview/introduction.md","filePath":"overview/introduction.md"}'),r={name:"overview/introduction.md"};function o(d,e,n,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h1><h2 id="用途与适用身份" tabindex="-1">用途与适用身份 <a class="header-anchor" href="#用途与适用身份" aria-label="Permalink to &quot;用途与适用身份&quot;">​</a></h2><p>星辉后台是一个 Spring Boot 管理 API 与 Vue 管理前端组成的开发底座。它提供已有管理功能和可核对的扩展路径，供项目管理者、开发者、运维人员理解当前实现。使用者先读本页，再按<a href="./reading-path.html">阅读路径</a>进入操作或开发教程。</p><p>应用中的管理操作需要登录和授权。文档公开阅读不授予接口权限，也不会加载用户的登录令牌。项目没有部门、岗位或组织树授权管理器；角色和菜单/操作码是当前授权模型。</p><h2 id="pages-静态阅读与体验" tabindex="-1">Pages 静态阅读与体验 <a class="header-anchor" href="#pages-静态阅读与体验" aria-label="Permalink to &quot;Pages 静态阅读与体验&quot;">​</a></h2><p>本次静态发布目标为<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/" target="_blank" rel="noreferrer">后台演示</a>和<a href="https://beidaomitu233.github.io/xinghui-admin-vue3/docs/" target="_blank" rel="noreferrer">文档中心</a>。部署状态以<a href="https://github.com/beidaomitu233/xinghui-admin-vue3/actions" target="_blank" rel="noreferrer">公开仓库 Actions</a>及实际 HTTP 验收为准，不在发布前宣称目标链接已验证。</p><p>演示只使用浏览器本地示例数据，手册是静态阅读内容；它们不连接真实后端或供应商，也不等于后端正式发行或完整应用质量 CI。下文源码基线、配置和权限教程仍面向真实应用，不用演示构建提交替换其依据。子路径部署见<a href="./../operations/deployment.html#github-pages">部署教程</a>。</p><h2 id="两个代码仓库怎样配合" tabindex="-1">两个代码仓库怎样配合 <a class="header-anchor" href="#两个代码仓库怎样配合" aria-label="Permalink to &quot;两个代码仓库怎样配合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>代码位置</th><th>当前职责</th><th>核对入口</th></tr></thead><tbody><tr><td>后端 <code>system-admin</code></td><td>登录、管理 API、业务服务、Flyway 迁移</td><td><code>system-admin/src/main/java/com/xinghuiTec/controller</code> 和 <code>src/main/resources/db/migration</code></td></tr><tr><td>后端 <code>system-framework</code></td><td>安全与框架配置</td><td>模块源码；接口的 <code>@PreAuthorize</code> 仍是操作边界</td></tr><tr><td>后端 <code>common</code></td><td>响应、缓存和基础工具</td><td><code>common/common-core</code> 等子模块</td></tr><tr><td>后端 <code>web-admin</code>、<code>web-app</code></td><td>示例启动模块</td><td>根 <code>pom.xml</code> 的模块列表；不是完整业务应用交付证明</td></tr><tr><td>前端 <code>apps/web-ele</code></td><td>Element Plus 管理应用和本项目页面</td><td><code>src/views</code>、<code>src/api</code>、<code>src/composables</code></td></tr><tr><td>前端 <code>packages</code>、<code>internal</code></td><td>Vben 派生组件、适配、工程配置</td><td>每个包的实际导出与本项目使用位置</td></tr><tr><td>前端 <code>apps/docs/content</code></td><td>统一公开文档正文</td><td>本站所有章节，不复制维护旧后端教程</td></tr></tbody></table><p>当前三个一级菜单是“系统管理、通用能力、运行维护”，同组直接列出已授权功能；仍有效页面沿用原地址。个人收件箱是已认证的个人入口，没有通用配置权限的用户也可看到只含个人入口的通用组。详见<a href="./../features/menus.html">菜单</a>和<a href="./../features/authorization.html">授权</a>。</p><h2 id="第一次接手时做什么" tabindex="-1">第一次接手时做什么 <a class="header-anchor" href="#第一次接手时做什么" aria-label="Permalink to &quot;第一次接手时做什么&quot;">​</a></h2><ol><li>确认前后端候选 commit 配对，而不是只读前端包版本或 Maven SNAPSHOT。文档源码依据是后端 <code>5f4746ddabb4bdeb0eaba74f7808d809b277306c</code>、前端 <code>3b6a4141d84b207b5380d667e6100dc585a64d62</code>；文档站本身随后增加，未创建正式发布 Tag。</li><li>按<a href="./../guide/environment.html">环境准备</a>配置工具和自己拥有的数据库、缓存、对象存储；按<a href="./../guide/configuration.html">运行配置</a>设置所需环境变量。不要把仓库示例当成生产凭据。</li><li>按<a href="./../guide/first-login.html">首次登录</a>处理初始账号，再完成<a href="./../guide/verification.html">运行验证</a>。</li><li>通过<a href="./capabilities.html">功能边界</a>判断哪些能力适合立即使用，哪些需要供应商或部署条件。</li><li>增加功能前读<a href="./../development/structure.html">项目结构</a>、<a href="./../development/routes-permissions.html">路由与权限</a>和<a href="./../reference/database-migrations.html">迁移</a>。</li></ol><p>正常结果是开发者知道两个仓库各自承担什么、部署版本如何识别，以及一个操作的页面和服务端检查位置。文档的成功示例描述正常流程，不替代你部署环境的验证。</p><h2 id="本地阅读文档" tabindex="-1">本地阅读文档 <a class="header-anchor" href="#本地阅读文档" aria-label="Permalink to &quot;本地阅读文档&quot;">​</a></h2><p>前端仓库根目录先安装锁定依赖，再启动文档包：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @xinghui/docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开命令输出地址的 <code>/docs/</code> 路径。发布文档前，使用以下命令检查并构建静态产物：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @xinghui/docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @xinghui/docs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>正常结果是首页、侧栏、页内目录与本地全文搜索可用，构建输出 <code>apps/docs/.vitepress/dist</code>。有缺章、坏链接或不存在的标题锚点时应修正文档后重跑，不关闭完整检查。按钮“复制代码”复制上面的命令文本；执行前按当前环境阅读相应章节。</p><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><ul><li><strong>页面不出现</strong>：先核对当前身份、角色授权及平台访问规则；不要直接在前端添加可见菜单来绕过服务端。相关章节见<a href="./../development/tenant-platform.html">租户与平台</a>。</li><li><strong>按旧说明访问已删模块</strong>：资料示例、网站管理、下载管理、页面管理已退役；当前保留资讯。不要按旧迁移或任务记录重建这些模块。</li><li><strong>后台可运行，文档深页 404</strong>：文档是独立静态产物，部署 <code>/docs/</code> 和其实际 <code>.html</code> 文件；见<a href="./../operations/deployment.html">部署运维</a>。</li><li><strong>版本名称看起来不一致</strong>：前端包版本沿用上游，后端为 SNAPSHOT；以<a href="./../releases/versions.html">候选版本</a>的源码配对及产物摘要识别部署组合。</li></ul><h2 id="参考结构与上游归属" tabindex="-1">参考结构与上游归属 <a class="header-anchor" href="#参考结构与上游归属" aria-label="Permalink to &quot;参考结构与上游归属&quot;">​</a></h2><p>本站借鉴 <a href="https://doc.vben.pro/guide/introduction/vben.html" target="_blank" rel="noreferrer">Vben</a>的分层阅读、<a href="https://github.com/pure-admin/pure-admin-doc" target="_blank" rel="noreferrer">Pure 官方文档源码</a>的新手教程组织、<a href="https://help.jeecg.com/" target="_blank" rel="noreferrer">Jeecg 文档中心</a>的功能/开发分类，以及<a href="https://doc.iocoder.cn/" target="_blank" rel="noreferrer">芋道开发指南</a>的全栈阅读路径。这里只参考组织方式，正文与参数来自星辉实际代码，不复制其业务能力或把项目流行度当成星辉质量证明。</p><p>前端派生自 <a href="https://github.com/vbenjs/vue-vben-admin" target="_blank" rel="noreferrer">Vue Vben Admin</a>，站点使用 <a href="https://vuejs.github.io/vitepress/v1/guide/getting-started" target="_blank" rel="noreferrer">VitePress</a>。保留仓库已有 LICENSE 和上游归属；当前文档不替代公开发行前的许可确认，也不使用上游仓库作为星辉反馈地址。</p><h2 id="实际源码来源" tabindex="-1">实际源码来源 <a class="header-anchor" href="#实际源码来源" aria-label="Permalink to &quot;实际源码来源&quot;">​</a></h2><ul><li>后端 <code>pom.xml</code>：模块和 JDK/Spring Boot 版本。</li><li>后端 <code>system-admin/src/main/resources/application.yml</code>：数据库、Flyway、租户默认配置。</li><li>后端 <code>system-admin/src/main/resources/db/migration/V20261013_170__menu_consolidation.sql</code>：三个分组和旧地址保留。</li><li>前端 <code>apps/web-ele/src/router/routes-helper.ts</code>：动态菜单与受保护个人入口。</li><li>前端 <code>apps/web-ele/src/preferences.ts</code>：后端动态路由模式、默认首页。</li></ul>`,26)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
